import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'closed';

interface Project {
  id: string;
  name: string;
  quotaUsed: number;
  status: ProjectStatus;
}

const projects: Project[] = [
  { id: 'p1', name: 'Атлас', quotaUsed: 82, status: 'active' },
  { id: 'p2', name: 'Кобра', quotaUsed: 45, status: 'active' },
  { id: 'p3', name: 'Дельта', quotaUsed: 100, status: 'closed' },
  { id: 'p4', name: 'Меридиан', quotaUsed: 12, status: 'paused' },
  { id: 'p5', name: 'Орион', quotaUsed: 67, status: 'active' },
  { id: 'p6', name: 'Пульсар', quotaUsed: 30, status: 'paused' },
  { id: 'p7', name: 'Квант', quotaUsed: 95, status: 'active' },
  { id: 'p8', name: 'Нептун', quotaUsed: 20, status: 'closed' },
  { id: 'p9', name: 'Вектор', quotaUsed: 55, status: 'active' },
  { id: 'p10', name: 'Символ', quotaUsed: 8, status: 'paused' },
  { id: 'p11', name: 'Горизонт', quotaUsed: 73, status: 'active' },
  { id: 'p12', name: 'Зенит', quotaUsed: 40, status: 'closed' },
];

const statusFilters: { value: ProjectStatus; label: string }[] = [
  { value: 'active', label: 'Активен' },
  { value: 'paused', label: 'На паузе' },
  { value: 'closed', label: 'Закрыт' },
];

const statusBadgeTone: Record<ProjectStatus, 'success' | 'warning' | 'default'> = {
  active: 'success',
  paused: 'warning',
  closed: 'default',
};

const statusBadgeLabel: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  closed: 'Закрыт',
};

const pageSize = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(
    statusFilters.map((filter) => filter.value)
  );
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((value) => value !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(statusFilters.map((filter) => filter.value));
    setPage(1);
  };

  const filteredProjects = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / pageSize));
  const visibleProjects = filteredProjects.slice((page - 1) * pageSize, page * pageSize);

  return (
    <div
      className="jx-surface"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        padding: 20,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
        {statusFilters.map((filter) => {
          const isActive = activeStatuses.includes(filter.value);
          return (
            <JxChip
              key={filter.value}
              active={isActive}
              removable={isActive}
              onRemove={() => toggleStatus(filter.value)}
              onClick={() => {
                if (!isActive) toggleStatus(filter.value);
              }}
            >
              {filter.label}
            </JxChip>
          );
        })}
      </div>

      {filteredProjects.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          message="Попробуйте выбрать другой статус или сбросить фильтры."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 16,
                  padding: '12px 8px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <span
                  style={{
                    flex: 1,
                    color: 'var(--jx-text)',
                    fontFamily: 'var(--jx-font-sans)',
                    fontWeight: 600,
                  }}
                >
                  {project.name}
                </span>
                <JxProgressCircle value={project.quotaUsed} showValue />
                <JxBadge tone={statusBadgeTone[project.status]} dot>
                  {statusBadgeLabel[project.status]}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

